pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assumed strictly positive; if violated, treat as "not close" safely.
    if tol <= 0 {
        return false;
    }

    let t: i16 = tol as i16;
    let diff: i16 = (a as i16) - (b as i16);

    // Strictly within (-tol, tol)
    diff > -t && diff < t
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert_eq!(a.len(), b.len(), "Input arrays must have equal length");

    let mut result = Vec::with_capacity(a.len());
    for (x, y) in a.into_iter().zip(b.into_iter()) {
        result.push(is_close_i8(x, y, tol));
    }
    result
}

